// ── Utilitaires DOM ───────────────────────────────────────────
const $  = (sel, ctx = document) => ctx.querySelector(sel);
const $$ = (sel, ctx = document) => [...ctx.querySelectorAll(sel)];
const show = (...els) => els.forEach(e => e && e.classList.remove("hidden"));
const hide = (...els) => els.forEach(e => e && e.classList.add("hidden"));

function toast(msg, type = "info") {
  const t = document.createElement("div");
  t.className = `toast toast--${type}`;
  t.textContent = msg;
  document.getElementById("toasts").appendChild(t);
  setTimeout(() => t.remove(), 3500);
}

function setLoading(btn, loading) {
  if (!btn) return;
  if (loading) { btn.dataset.orig = btn.textContent; btn.textContent = "…"; btn.disabled = true; }
  else { btn.textContent = btn.dataset.orig || btn.textContent; btn.disabled = false; }
}

// Échappement systématique des données affichées via innerHTML.
// Les valeurs venant de Firestore ou des saisies utilisateur ne doivent jamais
// être interprétées comme du HTML exécutable.
function h(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

// Argument JavaScript sûr lorsqu'une ancienne portion d'interface utilise encore
// un gestionnaire onclick inline. Le JSON est ensuite échappé pour l'attribut HTML.
function ja(value) {
  return h(JSON.stringify(String(value ?? "")));
}

function dateLocaleISO(date = new Date()) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, "0");
  const d = String(date.getDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

function heureLocale(iso) {
  if (!iso) return "";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit" });
}

function formatMontant(val) {
  return Number(val || 0).toLocaleString("fr-FR", { minimumFractionDigits: 2 }) + " €";
}

// ── Badge état réseau (hors-ligne / synchro) ──────────────────
function renderNetworkBadge() {
  return `<span id="network-badge" class="network-badge ${isOnline() ? 'network-badge--online' : 'network-badge--offline'}">${isOnline() ? '🟢 En ligne' : '🔴 Hors-ligne'}</span>`;
}

function bindNetworkBadge() {
  const badge = document.getElementById("network-badge");
  if (!badge) return () => {};
  return onNetworkChange((online) => {
    const b = document.getElementById("network-badge");
    if (!b) return;
    b.textContent = online ? '🟢 En ligne' : '🔴 Hors-ligne';
    b.className = `network-badge ${online ? 'network-badge--online' : 'network-badge--offline'}`;
    if (online) toast("Connexion rétablie — synchronisation en cours…", "success");
    else toast("Mode hors-ligne — tes saisies seront synchronisées au retour du réseau", "info");
  });
}

function stopUnsubs() {
  APP.unsubs.forEach(fn => fn && fn());
  APP.unsubs = [];
}

// ── Routing par hash ──────────────────────────────────────────
const ROUTES = {
  "#login":              renderLogin,
  "#dashboard":          renderDashboard,
  "#secteurs":           renderSecteurs,
  "#equipes":            renderEquipes,
  "#passages":           renderPassages,
  "#relances":           renderRelances,
  "#historique":         renderHistorique,
  "#classement":         renderClassement,
  "#statistiques":       renderStatistiques,
  "#journal":            renderJournal,
  "#config":             renderConfig,
  "#terrain":            renderTerrain,
  "#terrain-passages":   renderTerrainPassages
};

function naviguer(hash) {
  // Si le hash cible est déjà celui de l'URL, le navigateur ne déclenche
  // aucun évènement "hashchange" (rien ne change dans l'URL) : on rend
  // la route nous-mêmes pour ne pas rester bloqué sur l'écran courant
  // (ex. "Changer de caserne" cliqué depuis #dashboard, qui doit se
  // re-rendre bien que le hash reste #dashboard).
  if (window.location.hash === hash) {
    const fn = ROUTES[hash];
    if (fn) fn(); else renderLogin();
  } else {
    window.location.hash = hash;
  }
}

window.addEventListener("hashchange", () => {
  const hash = window.location.hash || "#login";
  const fn   = ROUTES[hash];
  if (fn) fn();
  else renderLogin();
});

// ── Bootstrap ─────────────────────────────────────────────────
// Gérer le retour de redirection Google Auth
getLoginRedirect().then(async (result) => {
  if (result?.user) {
    const admin = await isAdmin(result.user.email);
    if (!admin) {
      toast("Accès refusé : email non autorisé", "error");
      await logoutGoogle();
    }
    // onAuth prend le relais pour router
  }
}).catch((e) => {
  if (e?.code !== "auth/no-auth-event") {
    console.warn("Redirect result error:", e?.message);
  }
});

onAuth(async (user) => {
  // ── Aucune session : en ouvrir une (anonyme) puis attendre le rappel ──
  if (!user) {
    try {
      await assurerSession();
      return;   // onAuth sera rappelé avec la session anonyme
    } catch(e) {
      toast("Impossible d'ouvrir une session. Vérifie ta connexion.", "error");
      naviguer("#login");
      return;
    }
  }

  // ── Session anonyme : c'est un équipier (ou un visiteur sur l'écran de connexion) ──
  if (user.isAnonymous) {
    const sessionEquipe = sessionStorage.getItem("equipe");
    if (sessionEquipe) {
      try {
        const eq = JSON.parse(sessionEquipe);
        APP.role = "equipier";
        APP.user = eq;
        APP.equipeId  = eq.id;
        APP.equipeNom = eq.nom;
        definirOrganisationApp(eq.organisationId || null);
        appliquerOrganisation(JSON.parse(sessionStorage.getItem("organisationInfo") || "null"));
        APP.membre    = sessionStorage.getItem("membre") || null;
        naviguer("#terrain");
        return;
      } catch(e) { sessionStorage.removeItem("equipe"); }
    }
    naviguer("#login");
    return;
  }

  // ── Session Google : vérifier les droits d'administration ──
  try {
    const admin = await isAdmin(user.email);
    if (admin) {
      APP.role = "admin";
      APP.user = user;
      if (await resoudreOrganisationAdmin(user.email)) {
        demarrerPlanificateurResume();
        const hash = window.location.hash;
        naviguer(ROUTES[hash] && hash !== "#login" ? hash : "#dashboard");
      }
      return;
    }
    toast("Accès refusé : " + user.email + " n'est pas administrateur.", "error");
    await logoutGoogle();
    await assurerSession();   // repasser en session anonyme pour l'accès équipier
  } catch(e) {
    toast("Erreur de vérification : " + e.message, "error");
    await logoutGoogle();
    await assurerSession();
  }
});

// ── Grille de choix de caserne (par logo), partagée équipier/admin ──
// Initiales de repli tant qu'une caserne n'a pas encore de vrai logo
// (logoBase64 null) — dérivées du slug, ex. "saint-andre" → "SA".
function initialesCaserne(org) {
  return (org.slug || org.nom || "?").split(/[-\s]+/).map(m => m[0]).join("").toUpperCase().slice(0, 3);
}
function rendreTuileCaserne(org) {
  return `
    <button type="button" class="caserne-tuile" data-slug="${h(org.slug)}">
      ${org.logoBase64
        ? `<img src="${org.logoBase64}" alt="">`
        : `<span class="caserne-initiales" style="background:${h(org.couleur || 'var(--rouge)')}">${initialesCaserne(org)}</span>`}
      <span class="caserne-nom">${h(org.nom || org.slug)}</span>
    </button>
  `;
}

// Logo effectif d'une organisation : celui de son document Firestore, ou
// null si la caserne n'en a pas encore (repli sur les initiales, voir
// logoCaserneHTML() plus bas).
function resoudreLogoOrganisation(org) {
  return org?.logoBase64 || null;
}

// Met à jour nom/logo/couleur affichés pour la caserne connectée à partir
// de son document organisations/{slug} — à appeler partout où l'app change
// de caserne (login admin/équipier, choix du super-admin), en plus de
// definirOrganisationApp() qui gère l'ID côté données.
function appliquerOrganisation(org) {
  APP.organisationNom     = org?.nom || null;
  APP.organisationLogo    = resoudreLogoOrganisation(org);
  APP.organisationCouleur = org?.couleur || null;
}

// Logo de la caserne connectée, ou repli sur des initiales colorées si
// aucun logo n'est disponible. `style` : déclarations CSS inline pour la
// taille/forme, partagées entre l'image et le repli.
function logoCaserneHTML(style) {
  if (APP.organisationLogo) {
    return `<img src="${APP.organisationLogo}" alt="${h(APP.organisationNom || 'Caserne')}" style="${style}">`;
  }
  const initiales = initialesCaserne({ nom: APP.organisationNom, slug: APP.organisationId });
  return `<span style="${style}display:flex;align-items:center;justify-content:center;background:${h(APP.organisationCouleur || '#E50410')};color:#fff;font-weight:700;">${initiales}</span>`;
}

