function bindLoginEvents() {
  // Tabs
  $$(".tab-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      $$(".tab-btn").forEach(b => b.classList.remove("tab-btn--active"));
      btn.classList.add("tab-btn--active");
      const tab = btn.dataset.tab;
      $$(".tab-panel").forEach(p => p.classList.add("hidden"));
      document.getElementById(`tab-${tab}`).classList.remove("hidden");
    });
  });

  // Google — signInWithPopup
  const btnGoogle = document.getElementById("btn-google");
  if (btnGoogle) {
    btnGoogle.addEventListener("click", async () => {
      setLoading(btnGoogle, true);
      try {
        const result = await loginGoogle();
        if (result?.user) {
          const admin = await isAdmin(result.user.email);
          if (admin) {
            APP.role = "admin";
            APP.user = result.user;
            if (await resoudreOrganisationAdmin(result.user.email)) {
              naviguer("#dashboard");
            }
          } else {
            toast("Accès refusé : " + result.user.email + " n\'est pas administrateur.", "error");
            await logoutGoogle();
            setLoading(btnGoogle, false);
          }
        }
      } catch (e) {
        if (e.code !== "auth/popup-closed-by-user") {
          toast("Erreur de connexion : " + e.message, "error");
        }
        setLoading(btnGoogle, false);
      }
    });
  }

  // Choix de la caserne par logo (chantier multi-tenant, point 3)
  let orgIdentifiee = null;

  const etapeCaserne = document.getElementById("etape-caserne");
  const etapePin     = document.getElementById("etape-pin");

  function afficherEtapePin(org) {
    orgIdentifiee = org;
    etapeCaserne && etapeCaserne.classList.add("hidden");
    etapePin && etapePin.classList.remove("hidden");
    const nomEl = document.getElementById("pin-caserne-nom");
    if (nomEl) nomEl.textContent = org.nom || org.slug;
  }
  function afficherEtapeCaserne() {
    orgIdentifiee = null;
    pinSaisi = "";
    etapePin && etapePin.classList.add("hidden");
    etapeCaserne && etapeCaserne.classList.remove("hidden");
  }

  async function afficherGrilleCasernes() {
    const grille = document.getElementById("grille-casernes");
    const errEl  = document.getElementById("caserne-error");
    if (!grille) return;
    errEl && errEl.classList.add("hidden");
    try {
      const organisations = (await listerOrganisations()).filter(o => o.actif);
      grille.innerHTML = organisations.map(rendreTuileCaserne).join("");
      grille.querySelectorAll(".caserne-tuile").forEach(btn => {
        btn.addEventListener("click", () => {
          const org = organisations.find(o => o.slug === btn.dataset.slug);
          if (org) afficherEtapePin(org);
        });
      });
    } catch (e) {
      errEl && errEl.classList.remove("hidden");
    }
  }
  afficherGrilleCasernes();
  document.getElementById("btn-changer-caserne")?.addEventListener("click", afficherEtapeCaserne);

  // PIN
  let pinSaisi = "";
  function updatePinDisplay() {
    const display = document.getElementById("pin-display");
    if (!display) return;
    display.textContent = pinSaisi.padEnd(4, "_");
  }

  $$(".pin-key").forEach(btn => {
    btn.addEventListener("click", async () => {
      if (!orgIdentifiee) return;
      const key = btn.dataset.key;
      if (key === "⌫") {
        pinSaisi = pinSaisi.slice(0, -1);
        updatePinDisplay();
        return;
      }
      if (key === "") return;
      if (pinSaisi.length >= 4) return;
      pinSaisi += key;
      updatePinDisplay();

      if (pinSaisi.length === 4) {
        const errEl = document.getElementById("pin-error");
        try {
          const equipe = await loginPin(orgIdentifiee.slug, pinSaisi);
          if (equipe) {
            APP.role = "equipier";
            APP.user = equipe;
            APP.equipeId  = equipe.id;
            APP.equipeNom = equipe.nom;
            definirOrganisationApp(equipe.organisationId || orgIdentifiee.slug);
            appliquerOrganisation(orgIdentifiee);
            sessionStorage.setItem("equipe", JSON.stringify(equipe));
            sessionStorage.setItem("organisationInfo", JSON.stringify({
              nom: APP.organisationNom, logoBase64: APP.organisationLogo, couleur: APP.organisationCouleur
            }));
            // Si l'équipe a plusieurs membres, demander qui se connecte
            const membres = (equipe.membres || []).filter(Boolean);
            if (membres.length > 1) {
              afficherChoixMembre(equipe, membres);
            } else {
              const seul = membres[0] || equipe.nom;
              APP.membre = seul;
              sessionStorage.setItem("membre", seul);
              naviguer("#terrain");
            }
          } else {
            errEl && errEl.classList.remove("hidden");
            pinSaisi = "";
            updatePinDisplay();
            setTimeout(() => errEl && errEl.classList.add("hidden"), 2500);
          }
        } catch(e) {
          toast("Erreur : " + e.message, "error");
          pinSaisi = "";
          updatePinDisplay();
        }
      }
    });
  });
}


