// ── Parser CSV robuste (gère les guillemets et virgules dans les champs) ──
function parseCSVLine(line) {
  const out = [];
  let cur = '', inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (inQuotes) {
      if (ch === '"') {
        if (line[i+1] === '"') { cur += '"'; i++; }  // guillemet échappé ""
        else inQuotes = false;
      } else cur += ch;
    } else {
      if (ch === '"') inQuotes = true;
      else if (ch === ',') { out.push(cur); cur = ''; }
      else cur += ch;
    }
  }
  out.push(cur);
  return out.map(v => v.trim());
}

// Découpe le texte CSV en lignes en respectant les sauts de ligne dans les guillemets
function parseCSV(text) {
  const lignes = [];
  let cur = '', inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === '"') { inQuotes = !inQuotes; cur += ch; }
    else if ((ch === '\n' || ch === '\r') && !inQuotes) {
      if (cur.trim()) lignes.push(cur);
      cur = '';
      if (ch === '\r' && text[i+1] === '\n') i++;
    } else cur += ch;
  }
  if (cur.trim()) lignes.push(cur);
  return lignes.map(parseCSVLine);
}

