function bindLogout() {
  document.getElementById("btn-changer-caserne-admin")?.addEventListener("click", () => {
    sessionStorage.removeItem("adminOrganisationId");
    afficherChoixCaserneAdmin();
  });
  document.getElementById("btn-logout")?.addEventListener("click", async () => {
    stopUnsubs();
    if (APP.role === "admin") await logoutGoogle();
    sessionStorage.removeItem("equipe");
    sessionStorage.removeItem("membre");
    sessionStorage.removeItem("organisationInfo");
    sessionStorage.removeItem("adminOrganisationId");
    APP.role = null; APP.user = null; APP.equipeId = null; APP.equipeNom = null; APP.membre = null; APP.estSuperAdmin = false;
    appliquerOrganisation(null);
    definirOrganisationApp(null);
    try { await assurerSession(); } catch(e) {}   // garder une session pour l'accès PIN
    naviguer("#login");
  });
  bindMobileMenu();
}

function bindMobileMenu() {
  const btn = document.getElementById("btn-menu-toggle");
  const sidebar = document.getElementById("sidebar");
  const overlay = document.getElementById("sidebar-overlay");
  if (!btn || !sidebar || !overlay) return;

  const closeMenu = () => {
    sidebar.classList.remove("sidebar--open");
    overlay.classList.add("hidden");
  };
  const openMenu = () => {
    sidebar.classList.add("sidebar--open");
    overlay.classList.remove("hidden");
  };

  btn.addEventListener("click", () => {
    sidebar.classList.contains("sidebar--open") ? closeMenu() : openMenu();
  });
  overlay.addEventListener("click", closeMenu);
  // Fermer le menu après avoir cliqué un lien de navigation
  sidebar.querySelectorAll(".sidebar-link").forEach(link => {
    link.addEventListener("click", closeMenu);
  });
}

