async function renderSecteurs() {
  if (APP.role !== "admin") { naviguer("#login"); return; }
  stopUnsubs();

  document.getElementById("main").innerHTML = layoutAdmin("#secteurs", `
    <div class="page-header">
      <h1>Secteurs géographiques</h1>
      <div style="display:flex; gap:8px; flex-wrap:wrap;">
        <button id="btn-vider-secteurs" class="btn btn--danger">🗑️ Tout supprimer</button>
        <button id="btn-import-csv" class="btn btn--ghost">📥 Importer CSV</button>
        <button id="btn-add-secteur" class="btn btn--primary">+ Nouveau secteur</button>
      </div>
    </div>
    <div class="filter-bar">
      <input id="search-secteur" class="input input--sm" placeholder="🔍 Rechercher une commune ou un secteur…" style="max-width:320px;">
    </div>
    <div id="secteurs-list"><div class="loader">Chargement…</div></div>
    <div id="modal-secteur" class="modal hidden"></div>
    <input type="file" id="input-csv" accept=".csv" class="hidden">
  `);
  bindLogout();

  let _secteursCache = [];

  document.getElementById("search-secteur")?.addEventListener("input", (e) => {
    const q = e.target.value.trim().toLowerCase();
    const filtered = q
      ? _secteursCache.filter(s =>
          s.commune.toLowerCase().includes(q) || s.nom.toLowerCase().includes(q))
      : _secteursCache;
    renderSecteursList(filtered);
  });

  document.getElementById("btn-add-secteur")?.addEventListener("click", () => showSecteurModal());

  document.getElementById("btn-import-csv")?.addEventListener("click", () => {
    document.getElementById("input-csv").click();
  });

  document.getElementById("btn-vider-secteurs")?.addEventListener("click", async () => {
    const secteurs = await lireSecteurs();
    if (secteurs.length === 0) { toast("Aucun secteur à supprimer", "info"); return; }

    if (!confirm(
      `⚠️ SUPPRIMER TOUS LES SECTEURS ?\n\n` +
      `${secteurs.length} secteur(s) vont être définitivement supprimés.\n` +
      `Les passages enregistrés ne seront plus rattachés à aucun secteur.\n\n` +
      `Cette action est IRRÉVERSIBLE.`
    )) return;

    const saisie = prompt(
      `Dernière confirmation.\n\nTape SUPPRIMER (en majuscules) pour confirmer la suppression des ${secteurs.length} secteurs :`
    );
    if (saisie !== "SUPPRIMER") { toast("Suppression annulée", "info"); return; }

    const btn = document.getElementById("btn-vider-secteurs");
    setLoading(btn, true);
    let ok = 0, ko = 0;
    for (const s of secteurs) {
      try { await supprimerSecteur(s.id); ok++; }
      catch(e) { console.error("Erreur suppression", s.nom, e); ko++; }
    }
    setLoading(btn, false);
    toast(`${ok} secteur(s) supprimé(s)${ko ? `, ${ko} erreur(s)` : ''}`, ko ? "error" : "success");
  });

  document.getElementById("input-csv")?.addEventListener("change", async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const text = await file.text();
    const rows2d = parseCSV(text);
    if (rows2d.length < 2) { toast("CSV vide ou illisible", "error"); return; }
    const headers = rows2d[0];
    let created = 0, updated = 0, errors = 0;

    // Index des secteurs existants par "nom|commune" pour éviter les doublons
    const existants = await lireSecteurs();
    const clef = (nom, commune) => `${nom.trim().toLowerCase()}|${commune.trim().toLowerCase()}`;
    const index = new Map(existants.map(s => [clef(s.nom, s.commune), s]));

    for (let i = 1; i < rows2d.length; i++) {
      const values = rows2d[i];
      const row = {};
      headers.forEach((h, idx) => row[h] = (values[idx] || '').trim());

      if (!row.nom || !row.commune) continue;

      const donnees = {
        nom: row.nom,
        commune: row.commune,
        description: row.description || '',
        rues: row.rues ? row.rues.split(';').map(r => r.trim()).filter(Boolean) : [],
        couleur: row.couleur || '#EF4444',
        objectifCalendriers: row.objectif ? Math.max(0, parseInt(row.objectif, 10) || 0) : null
      };

      try {
        const existant = index.get(clef(row.nom, row.commune));
        if (existant) {
          await mettreAJourSecteur(existant.id, donnees);
          updated++;
        } else {
          await creerSecteur({ ...donnees, organisationId: APP.organisationId });
          created++;
        }
      } catch(err) {
        console.error('Erreur import ligne', i, err);
        errors++;
      }
    }
    toast(`Import terminé : ${created} créé(s), ${updated} mis à jour${errors ? `, ${errors} erreur(s)` : ''}`, errors ? "error" : "success");
    e.target.value = '';
  });

  const unsub = ecouterSecteurs((secteurs) => {
    _secteursCache = secteurs;
    const q = document.getElementById("search-secteur")?.value.trim().toLowerCase() || '';
    const filtered = q
      ? secteurs.filter(s => s.commune.toLowerCase().includes(q) || s.nom.toLowerCase().includes(q))
      : secteurs;
    renderSecteursList(filtered);
  });
  APP.unsubs.push(unsub);
}

function renderSecteursList(secteurs) {
  const list = document.getElementById("secteurs-list");
  if (!list) return;
  if (secteurs.length === 0) {
    const hasSearch = document.getElementById("search-secteur")?.value.trim();
    list.innerHTML = hasSearch
      ? `<p class="empty-state">Aucun secteur ne correspond à « ${hasSearch} ».</p>`
      : `<p class="empty-state">Aucun secteur. Commence par en créer un.</p>`;
    return;
  }
  const sorted = [...secteurs].sort((a, b) => (a.commune + a.nom).localeCompare(b.commune + b.nom));
  list.innerHTML = `
    <div class="secteurs-grid">
      ${sorted.map(s => `
        <div class="secteur-card secteur-card--${s.statut}" data-id="${s.id}">
          <div class="secteur-card-header">
            <span class="secteur-dot" style="background:${s.couleur || '#EF4444'}"></span>
            <strong>${h(s.nom)}</strong>
            <span class="badge badge--${s.statut}">${STATUT_LABEL[s.statut]}</span>
          </div>
          <div class="secteur-card-body">
            <div class="secteur-commune-label">${h(s.commune)}</div>
            <div class="secteur-equipe">${s.equipNom ? '👥 ' + h(s.equipNom) : '— Non affecté'}</div>
            <div class="secteur-montant">${formatMontant(s.totalCollecte)}</div>
            ${s.objectifCalendriers > 0 ? `<div class="secteur-objectif">🎯 Objectif : ${s.objectifCalendriers} calendriers</div>` : ''}
            ${s.rues?.length ? `<div class="secteur-rues">${h(s.rues.join(', '))}</div>` : ''}
          </div>
          <div class="secteur-card-actions">
            <button class="btn btn--sm btn--ghost" onclick="ficheDeRoute('${s.id}')" title="Fiche de route imprimable">🖨️</button>
            <button class="btn btn--sm btn--ghost" onclick="editSecteur('${s.id}')">✏️ Modifier</button>
            <button class="btn btn--sm btn--ghost" onclick="affecterSecteur('${s.id}')">👥 Affecter</button>
            ${s.statut !== 'termine' ? `<button class="btn btn--sm btn--ghost" onclick="clotureSecteur('${s.id}')">✅ Clôturer</button>` : ''}
            <button class="btn btn--sm btn--danger" onclick="deleteSecteur('${s.id}')">🗑️</button>
          </div>
        </div>
      `).join('')}
    </div>
  `;
}


// ════════════════════════════════════════════════════════════
//  FICHE DE ROUTE IMPRIMABLE (par secteur)
// ════════════════════════════════════════════════════════════

window.ficheDeRoute = async (secteurId) => {
  const secteur = await lireSecteur(secteurId);
  if (!secteur) { toast("Secteur introuvable", "error"); return; }

  const passages = await passagesDuSecteur(secteurId);
  const rues  = ruesDuSecteur(secteur);
  const notes = toutesLesNotes(secteur);
  const nrm = s => (s||'').toLowerCase().normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'');
  const secondaires = new Set(adressesSecondaires(secteur).map(nrm));
  const inhab       = new Set((secteur.inhabitees||[]).map(nrm));
  const noteParAdr  = {};
  notes.forEach(n => { noteParAdr[nrm(n.adresse)] = n.texte; });

  let totalFoyers = 0, dejaFaits = 0;
  const blocs = rues.map(r => {
    let nums = [];
    try { nums = numerosDeRue(secteur.commune, r.rue, r.restriction); } catch(e) {}
    const comp = lireComplements(secteur, r.rue);
    nums = [...new Set([...nums, ...comp])]
      .filter(n => !secondaires.has(nrm(`${n} ${r.rue}`)))
      .sort((a,b) => (parseInt(a)||9999) - (parseInt(b)||9999));
    nums.forEach(n => {
      const c = nrm(`${n} ${r.rue}`);
      if (!inhab.has(c)) totalFoyers++;
      if (passages.some(p => nrm(p.adresse) === c)) dejaFaits++;
    });
    return { rue: r.rue, nums, partagee: Array.isArray(r.restriction) };
  }).filter(b => b.nums.length > 0);

  const COLS = 14;
  const dateJour = new Date().toLocaleDateString('fr-FR',
    { day:'numeric', month:'long', year:'numeric' });

  const html = `<!DOCTYPE html><html lang="fr"><head><meta charset="utf-8">
<title>Fiche de route — ${h(secteur.nom)}</title>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
  @page { size:A4 portrait; margin:11mm 9mm 9mm; }
  *{box-sizing:border-box;margin:0;padding:0}
  body{font-family:'Inter',-apple-system,'Segoe UI',sans-serif;font-size:9.4pt;
       color:#22262e;-webkit-print-color-adjust:exact;print-color-adjust:exact}

  /* En-tête */
  .head{display:flex;align-items:center;gap:9pt;padding-bottom:7pt;
        border-bottom:2pt solid #E50410;margin-bottom:9pt}
  .head img{width:38pt;height:38pt;object-fit:contain;border-radius:50%;flex-shrink:0}
  .head-txt{flex:1}
  .head h1{font-size:17pt;font-weight:800;color:#E50410;letter-spacing:-.3pt;line-height:1.1}
  .head .commune{font-size:10pt;font-weight:600;color:#4A4E6A;margin-top:1pt}
  .head .amicale{font-size:7.6pt;color:#8b8f9c;margin-top:2pt;letter-spacing:.2pt;
                 text-transform:uppercase}
  .head-eq{text-align:right;font-size:8pt;color:#4A4E6A;flex-shrink:0}
  .head-eq strong{display:block;font-size:9.5pt;color:#22262e}

  /* Bandeau de synthèse */
  .kpis{display:flex;gap:6pt;margin-bottom:10pt}
  .kpi{flex:1;text-align:center;padding:5pt 3pt;border-radius:4pt;
       background:#f6f7fa;border:.6pt solid #e3e5ec}
  .kpi b{display:block;font-size:14pt;font-weight:800;line-height:1;color:#22262e}
  .kpi span{display:block;font-size:6.8pt;color:#8b8f9c;margin-top:2.5pt;
            text-transform:uppercase;letter-spacing:.3pt}
  .kpi--rouge{background:#fdecea;border-color:#f5b8b2}
  .kpi--rouge b{color:#E50410}

  /* Rues */
  .rue{margin-bottom:7.5pt;page-break-inside:avoid}
  .rue-head{display:flex;align-items:baseline;gap:5pt;padding:3pt 6pt;
            background:#2D3142;color:#fff;border-radius:3pt 3pt 0 0}
  .rue-head h2{font-size:9.8pt;font-weight:700;flex:1;letter-spacing:-.1pt}
  .rue-head .cnt{font-size:7.4pt;opacity:.75;font-weight:500}
  .rue-head .tag{font-size:6.4pt;background:rgba(255,255,255,.22);
                 padding:1pt 4pt;border-radius:6pt;font-weight:600}
  .grid{display:grid;grid-template-columns:repeat(${COLS},1fr);
        border:.6pt solid #d8dae2;border-top:none;border-radius:0 0 3pt 3pt;overflow:hidden}
  .cel{border-right:.5pt solid #e3e5ec;border-bottom:.5pt solid #e3e5ec;
       min-height:26pt;padding:2.5pt 1pt 1pt;text-align:center;position:relative}
  .cel:nth-child(${COLS}n){border-right:none}
  .cel .n{font-size:9pt;font-weight:700;display:block;line-height:1}
  .cel .nt{font-size:5.6pt;color:#B45309;display:block;line-height:1.15;
           margin-top:1pt;font-weight:600}
  .cel--fait{background:#eef0f4}
  .cel--fait .n{color:#9aa0ad}
  .cel--fait::after{content:'✓';position:absolute;top:1pt;right:2pt;
                    font-size:6pt;color:#16A34A;font-weight:800}
  .cel--inhab{background:repeating-linear-gradient(45deg,#f6f7fa,#f6f7fa 3pt,#eaecf1 3pt,#eaecf1 6pt)}
  .cel--inhab .n{color:#b4b8c2;text-decoration:line-through}
  .cel--vide{background:#fbfbfc;border-right:none;border-bottom:none}

  /* Bas de page */
  .row{display:flex;gap:8pt;margin-top:9pt;page-break-inside:avoid}
  .card{flex:1;border:.6pt solid #d8dae2;border-radius:4pt;padding:6pt 7pt}
  .card h3{font-size:8.6pt;font-weight:700;margin-bottom:4pt;color:#2D3142;
           letter-spacing:.1pt;text-transform:uppercase}
  .lg{display:flex;flex-wrap:wrap;gap:4pt 9pt;font-size:7.6pt;color:#5a5f6b}
  .lg i{display:inline-block;width:11pt;height:11pt;border-radius:2pt;
        border:.6pt solid #c4c8d1;text-align:center;line-height:10pt;
        font-size:6.6pt;font-weight:800;font-style:normal;margin-right:2.5pt;
        color:#22262e;background:#fff}
  .notes-l{font-size:7.8pt;line-height:1.5}
  .notes-l div{padding:1.5pt 0;border-bottom:.4pt dotted #dfe1e8}
  .notes-l div:last-child{border:none}
  .notes-l b{color:#22262e}
  .notes-l span{color:#B45309}

  .bilan{margin-top:9pt;border:.8pt solid #2D3142;border-radius:4pt;overflow:hidden;
         page-break-inside:avoid}
  .bilan h3{font-size:8.6pt;font-weight:700;background:#2D3142;color:#fff;
            padding:3.5pt 7pt;letter-spacing:.2pt;text-transform:uppercase}
  .bilan-in{padding:7pt}
  .champs{display:flex;gap:9pt}
  .champs+.champs{margin-top:8pt}
  .ch{flex:1}
  .ch label{font-size:7pt;color:#8b8f9c;text-transform:uppercase;letter-spacing:.3pt;
            font-weight:600}
  .ch .ln{border-bottom:.7pt solid #9aa0ad;height:16pt;margin-top:1pt}
  .ch--tot .ln{border-bottom-width:1.4pt;border-color:#E50410}
  .ch--tot label{color:#E50410;font-weight:700}

  .foot{margin-top:7pt;display:flex;justify-content:space-between;
        font-size:6.8pt;color:#b4b8c2;letter-spacing:.2pt}
  @media print{.noprint{display:none!important}}
  .noprint{margin-top:14pt;text-align:center}
  .noprint button{font-family:'Inter',sans-serif;padding:9pt 22pt;font-size:10.5pt;
    font-weight:700;background:#E50410;color:#fff;border:none;border-radius:6pt;cursor:pointer}
</style></head><body>

<div class="head">
  ${logoCaserneHTML("width:38pt;height:38pt;object-fit:contain;border-radius:50%;flex-shrink:0;")}
  <div class="head-txt">
    <h1>${h(secteur.nom)}</h1>
    <div class="commune">${h(secteur.commune)}</div>
    <div class="amicale">${h(APP.organisationNom || 'Amicale des Sapeurs-Pompiers')}</div>
  </div>
  <div class="head-eq">
    ${secteur.equipNom ? `<strong>${h(secteur.equipNom)}</strong>` : ''}
    Éditée le ${dateJour}
  </div>
</div>

<div class="kpis">
  <div class="kpi kpi--rouge"><b>${totalFoyers}</b><span>boîtes à visiter</span></div>
  <div class="kpi"><b>${blocs.length}</b><span>rue${blocs.length>1?'s':''}</span></div>
  ${dejaFaits ? `<div class="kpi"><b>${dejaFaits}</b><span>déjà saisis</span></div>` : ''}
</div>

${blocs.map(b => {
  const cels = b.nums.map(n => {
    const c   = nrm(`${n} ${b.rue}`);
    const fait= passages.some(p => nrm(p.adresse) === c);
    const inh = inhab.has(c);
    const nt  = noteParAdr[c];
    return `<div class="cel${fait?' cel--fait':''}${inh?' cel--inhab':''}">
      <span class="n">${n}</span>${nt?`<span class="nt">${h(nt.slice(0,13))}</span>`:''}
    </div>`;
  });
  const reste = (COLS - (cels.length % COLS)) % COLS;
  return `<div class="rue">
    <div class="rue-head">
      <h2>${h(b.rue)}</h2>
      ${b.partagee?'<span class="tag">portion</span>':''}
      <span class="cnt">${b.nums.length} boîte${b.nums.length>1?'s':''}</span>
    </div>
    <div class="grid">${cels.join('')}${'<div class="cel cel--vide"></div>'.repeat(reste)}</div>
  </div>`;
}).join('')}

<div class="row">
  <div class="card">
    <h3>Codes à noter</h3>
    <div class="lg">
      <span><i>D</i>Don</span><span><i>O</i>Offert</span>
      <span><i>R</i>Refus</span><span><i>A</i>Absent</span>
      <span><i style="background:#eef0f4">✓</i>Déjà saisi</span>
      <span><i style="text-decoration:line-through;color:#b4b8c2">12</i>Inhabité</span>
    </div>
  </div>
  ${notes.length ? `<div class="card">
    <h3>📌 Notes du secteur</h3>
    <div class="notes-l">
      ${notes.slice(0,8).map(n=>`<div><b>${h(n.adresse)}</b> — <span>${h(n.texte)}</span></div>`).join('')}
      ${notes.length>8?`<div style="color:#b4b8c2">… et ${notes.length-8} autre${notes.length-8>1?'s':''}</div>`:''}
    </div>
  </div>` : ''}
</div>

<div class="bilan">
  <h3>Bilan de la sortie</h3>
  <div class="bilan-in">
    <div class="champs">
      <div class="ch"><label>Date</label><div class="ln"></div></div>
      <div class="ch"><label>Nom de l'équipier</label><div class="ln"></div></div>
      <div class="ch"><label>Calendriers placés</label><div class="ln"></div></div>
    </div>
    <div class="champs">
      <div class="ch"><label>Espèces</label><div class="ln"></div></div>
      <div class="ch"><label>Chèques</label><div class="ln"></div></div>
      <div class="ch ch--tot"><label>Total remis</label><div class="ln"></div></div>
    </div>
  </div>
</div>

<div class="foot">
  <span>${h(APP.organisationNom || 'Amicale des Sapeurs-Pompiers')}</span>
  <span>${h(secteur.nom)} — ${h(secteur.commune)}</span>
</div>

<div class="noprint"><button onclick="window.print()">🖨️ Imprimer cette fiche</button></div>
</body></html>`;

  const w = window.open('', '_blank');
  if (!w) { toast("Autorise les fenêtres pop-up pour imprimer", "error"); return; }
  w.document.write(html);
  w.document.close();
};

window.editSecteur = async (id) => {
  const s = await lireSecteur(id);
  showSecteurModal(s);
};
window.deleteSecteur = async (id) => {
  if (!confirm("Supprimer ce secteur ? Tous ses passages seront orphelins.")) return;
  try { await supprimerSecteur(id); toast("Secteur supprimé", "success"); }
  catch(e) { toast(e.message, "error"); }
};
window.clotureSecteur = async (id) => {
  if (!confirm("Marquer ce secteur comme terminé ?")) return;
  try { await cloturerSecteur(id); toast("Secteur clôturé ✅", "success"); }
  catch(e) { toast(e.message, "error"); }
};
window.affecterSecteur = async (secteurId) => {
  const equipes = await lireEquipes();
  const modal = document.getElementById("modal-secteur");
  modal.innerHTML = `
    <div class="modal-inner">
      <h2>Affecter une équipe</h2>
      <select id="sel-equipe" class="input">
        <option value="">— Aucune (désaffecter) —</option>
        ${equipes.map(e => `<option value="${e.id}" data-nom="${h(e.nom)}">${h(e.nom)}</option>`).join('')}
      </select>
      <div class="modal-actions">
        <button id="btn-affecter" class="btn btn--primary">Confirmer</button>
        <button class="btn btn--ghost" onclick="closeModal()">Annuler</button>
      </div>
    </div>
  `;
  modal.classList.remove("hidden");
  document.getElementById("btn-affecter")?.addEventListener("click", async () => {
    const sel = document.getElementById("sel-equipe");
    const equipeId  = sel.value;
    const equipeNom = sel.options[sel.selectedIndex].dataset.nom || null;
    try {
      if (equipeId) await affecterEquipe(secteurId, equipeId, equipeNom);
      else await desaffecterEquipe(secteurId);
      toast("Affectation mise à jour ✅", "success");
      closeModal();
    } catch(e) { toast(e.message, "error"); }
  });
};

function showSecteurModal(secteur = null) {
  const modal = document.getElementById("modal-secteur");
  modal.innerHTML = `
    <div class="modal-inner">
      <h2>${secteur ? "Modifier le secteur" : "Nouveau secteur"}</h2>
      <label class="label">Nom du secteur *</label>
      <input id="s-nom" class="input" value="${h(secteur?.nom || '')}" placeholder="Ex: Centre-ville Nord">
      <label class="label">Commune *</label>
      <input id="s-commune" class="input" value="${h(secteur?.commune || '')}" placeholder="Ex: Nom de la commune">
      <label class="label">Description</label>
      <input id="s-desc" class="input" value="${h(secteur?.description || '')}" placeholder="Informations complémentaires">
      <label class="label">Rues / zones (une par ligne)</label>
      <textarea id="s-rues" class="input textarea" rows="4">${h((secteur?.rues || []).join('\n'))}</textarea>
      <label class="label">Couleur d'affichage</label>
      <input id="s-couleur" type="color" class="input input--color" value="${secteur?.couleur || '#EF4444'}">
      <label class="label">Objectif minimum de calendriers</label>
      <input id="s-objectif" type="number" min="0" step="1" class="input" value="${secteur?.objectifCalendriers ?? ''}" placeholder="Ex: 150 (laisser vide si aucun objectif)">
      <div class="modal-actions">
        <button id="btn-save-secteur" class="btn btn--primary">${secteur ? "Enregistrer" : "Créer"}</button>
        <button class="btn btn--ghost" onclick="closeModal()">Annuler</button>
      </div>
    </div>
  `;
  modal.classList.remove("hidden");
  document.getElementById("btn-save-secteur")?.addEventListener("click", async () => {
    const nom      = document.getElementById("s-nom").value.trim();
    const commune  = document.getElementById("s-commune").value.trim();
    const description = document.getElementById("s-desc").value.trim();
    const rues     = document.getElementById("s-rues").value.split('\n').map(r => r.trim()).filter(Boolean);
    const couleur  = document.getElementById("s-couleur").value;
    const objectifRaw = document.getElementById("s-objectif").value.trim();
    const objectifCalendriers = objectifRaw ? Math.max(0, parseInt(objectifRaw, 10) || 0) : null;
    if (!nom || !commune) { toast("Nom et commune obligatoires", "error"); return; }
    try {
      if (secteur) await mettreAJourSecteur(secteur.id, { nom, commune, description, rues, couleur, objectifCalendriers });
      else await creerSecteur({ nom, commune, description, rues, couleur, objectifCalendriers, organisationId: APP.organisationId });
      toast(secteur ? "Secteur mis à jour ✅" : "Secteur créé ✅", "success");
      closeModal();
    } catch(e) { toast(e.message, "error"); }
  });
}

window.closeModal = () => {
  $$(".modal").forEach(m => m.classList.add("hidden"));
};

// ════════════════════════════════════════════════════════════
//  ÉQUIPES
// ════════════════════════════════════════════════════════════

async function renderEquipes() {
  if (APP.role !== "admin") { naviguer("#login"); return; }
  stopUnsubs();

  document.getElementById("main").innerHTML = layoutAdmin("#equipes", `
    <div class="page-header">
      <h1>Équipes</h1>
      <div style="display:flex; gap:8px; flex-wrap:wrap;">
        <button id="btn-auto-affecter" class="btn btn--ghost">🔗 Affecter par nom</button>
        <button id="btn-vider-equipes" class="btn btn--danger">🗑️ Tout supprimer</button>
        <button id="btn-import-csv-equipe" class="btn btn--ghost">📥 Importer CSV</button>
        <button id="btn-add-equipe" class="btn btn--primary">+ Nouvelle équipe</button>
      </div>
    </div>
    <div id="equipes-list"><div class="loader">Chargement…</div></div>
    <div id="modal-equipe" class="modal hidden"></div>
    <input type="file" id="input-csv-equipe" accept=".csv" class="hidden">
  `);
  bindLogout();

  document.getElementById("btn-add-equipe")?.addEventListener("click", () => showEquipeModal());

  document.getElementById("btn-auto-affecter")?.addEventListener("click", async () => {
    if (!confirm("Affecter automatiquement chaque secteur à l'équipe portant son nom (ex: secteur \"Chambray\" → équipe \"Équipe Chambray\") ?\n\nLes secteurs déjà affectés à une autre équipe seront écrasés s'il y a correspondance.")) return;

    const btn = document.getElementById("btn-auto-affecter");
    setLoading(btn, true);
    try {
      const [equipes, secteurs] = await Promise.all([lireEquipes(), lireSecteurs()]);

      // Normalise un nom pour matcher : minuscules, sans accents, sans "équipe "
      const normalize = (s) => s
        .toLowerCase()
        .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
        .replace(/^equipe\s+/i, "")
        .trim();

      const equipesParNom = {};
      equipes.forEach(eq => { equipesParNom[normalize(eq.nom)] = eq; });

      let affectes = 0, sansMatch = 0;
      for (const s of secteurs) {
        const match = equipesParNom[normalize(s.nom)];
        if (match) {
          await affecterEquipe(s.id, match.id, match.nom);
          affectes++;
        } else {
          sansMatch++;
        }
      }
      toast(`Affectation automatique : ${affectes} secteur(s) affecté(s)${sansMatch ? `, ${sansMatch} sans correspondance` : ''}`, "success");
    } catch(e) {
      toast("Erreur : " + e.message, "error");
    }
    setLoading(btn, false);
  });

  document.getElementById("btn-import-csv-equipe")?.addEventListener("click", () => {
    document.getElementById("input-csv-equipe").click();
  });

  document.getElementById("btn-vider-equipes")?.addEventListener("click", async () => {
    const equipes = await lireEquipes();
    if (equipes.length === 0) { toast("Aucune équipe à supprimer", "info"); return; }

    if (!confirm(
      `⚠️ SUPPRIMER TOUTES LES ÉQUIPES ?\n\n` +
      `${equipes.length} équipe(s) vont être définitivement supprimées.\n` +
      `Les secteurs affectés perdront leur équipe.\n\n` +
      `Cette action est IRRÉVERSIBLE.`
    )) return;

    const saisie = prompt(
      `Dernière confirmation.\n\nTape SUPPRIMER (en majuscules) pour confirmer la suppression des ${equipes.length} équipes :`
    );
    if (saisie !== "SUPPRIMER") { toast("Suppression annulée", "info"); return; }

    const btn = document.getElementById("btn-vider-equipes");
    setLoading(btn, true);
    let ok = 0, ko = 0;
    for (const e of equipes) {
      try { await supprimerEquipe(e.id); ok++; }
      catch(err) { console.error("Erreur suppression", e.nom, err); ko++; }
    }
    setLoading(btn, false);
    toast(`${ok} équipe(s) supprimée(s)${ko ? `, ${ko} erreur(s)` : ''}`, ko ? "error" : "success");
  });

  document.getElementById("input-csv-equipe")?.addEventListener("change", async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const text = await file.text();
    const rows2d = parseCSV(text);
    if (rows2d.length < 2) { toast("CSV vide ou illisible", "error"); return; }
    const headers = rows2d[0];
    let created = 0, errors = 0;

    for (let i = 1; i < rows2d.length; i++) {
      const values = rows2d[i];
      const row = {};
      headers.forEach((h, idx) => row[h] = (values[idx] || '').trim());

      if (!row.nom || !row.pin) continue;

      try {
        await creerEquipe({
          nom: row.nom,
          pin: row.pin,
          membres: row.membres ? row.membres.split(';').map(m => m.trim()).filter(Boolean) : [],
          organisationId: APP.organisationId
        });
        created++;
      } catch(err) {
        console.error('Erreur import ligne', i, err);
        errors++;
      }
    }
    toast(`Import terminé : ${created} équipe(s) créée(s)${errors ? `, ${errors} erreur(s)` : ''}`, errors ? "error" : "success");
    e.target.value = '';
  });

  const unsub = ecouterEquipes(async (equipes) => {
    // Les PIN vivent dans une collection séparée : on les rattache pour l'affichage
    let pins = {};
    try { pins = await lirePins(); } catch(e) {}
    renderEquipesList(equipes.map(e => ({ ...e, pin: pins[e.id] || e.pin || null })));
  });
  APP.unsubs.push(unsub);
}

