// Détail des remises d'une équipe (vue admin)
window.voirRemises = async (equipeId) => {
  const equipe = await lireEquipe(equipeId);
  if (!equipe) return;
  const remises = (equipe.remises || []).slice().reverse();
  const stats = await statsGlobalesTournee();
  const eq = stats.parEquipe.find(x => x.id === equipeId);
  const collecte = eq ? eq.montant : 0;
  const remis = totalRemis(equipe);

  let modal = document.getElementById("modal-remises");
  if (!modal) {
    modal = document.createElement("div");
    modal.id = "modal-remises"; modal.className = "modal hidden";
    document.body.appendChild(modal);
  }
  modal.classList.remove("hidden");
  modal.innerHTML = `
    <div class="modal-inner">
      <h2>Remises — ${h(equipe.nom)}</h2>
      <div class="vr-resume">
        <div><span>Collecté</span><strong>${formatMontant(collecte)}</strong></div>
        <div><span>Remis</span><strong>${formatMontant(remis)}</strong></div>
        <div class="${collecte - remis > 0.01 ? 'vr-du' : 'vr-ok'}">
          <span>${collecte - remis > 0.01 ? 'Reste dû' : 'À jour'}</span>
          <strong>${collecte - remis > 0.01 ? formatMontant(collecte - remis) : '✅'}</strong>
        </div>
      </div>
      ${remises.length === 0 ? '<p class="empty-state">Aucune remise enregistrée.</p>' : `
      <div class="table-wrap">
        <table class="table">
          <thead><tr><th>Date</th><th>Espèces</th><th>Chèques</th><th>Total</th><th>Par</th><th></th></tr></thead>
          <tbody>
            ${remises.map(r => `
              <tr>
                <td>${new Date(r.date).toLocaleDateString('fr-FR',{day:'2-digit',month:'short',year:'2-digit'})}</td>
                <td>${r.especes ? formatMontant(r.especes) : '—'}</td>
                <td>${r.cheques ? formatMontant(r.cheques) : '—'}</td>
                <td><strong>${formatMontant(r.total)}</strong></td>
                <td>${h(r.parQui || '—')}</td>
                <td><button class="btn btn--sm btn--danger" onclick="supprRemise('${equipeId}','${r.id}')">🗑️</button></td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>`}
      <div class="modal-actions">
        <button class="btn btn--ghost" onclick="document.getElementById('modal-remises').classList.add('hidden')">Fermer</button>
      </div>
    </div>
  `;
};

window.supprRemise = async (equipeId, remiseId) => {
  if (!confirm("Supprimer cette remise ?")) return;
  try {
    await supprimerRemise(equipeId, remiseId);
    toast("Remise supprimée", "success");
    voirRemises(equipeId);
  } catch(e) { toast("Erreur : " + e.message, "error"); }
};

window.editEquipe = async (id) => {
  const equipes = await lireEquipes();
  const eq = equipes.find(e => e.id === id);
  showEquipeModal(eq);
};
window.deleteEquipe = async (id) => {
  if (!confirm("Supprimer cette équipe ?")) return;
  try { await supprimerEquipe(id); toast("Équipe supprimée", "success"); }
  catch(e) { toast(e.message, "error"); }
};

