async function renderStatistiques() {
  if (APP.role !== "admin") { naviguer("#login"); return; }
  stopUnsubs();

  document.getElementById("main").innerHTML = layoutAdmin("#statistiques", `
    <div class="page-header">
      <h1>📈 Statistiques</h1>
      <button id="btn-export-stats" class="btn btn--ghost">⬇️ Exporter</button>
    </div>
    <p style="font-size:.85rem;color:var(--ardoise-mid);margin-bottom:16px;line-height:1.5;">
      Analyse de la tournée en cours. Ces chiffres servent à calibrer les objectifs et les horaires de sortie de l'an prochain.
    </p>
    <div id="stats-content"><div class="loader">Calcul en cours…</div></div>
  `);
  bindLogout();

  let lignesSecteur = [];

  try {
    const [passages, secteurs] = await Promise.all([
      fsGetAllOrg(COLLECTIONS.PASSAGES),
      lireSecteurs()
    ]);
    const el = document.getElementById("stats-content");

    if (passages.length === 0) {
      el.innerHTML = `<p class="empty-state">Aucun passage enregistré pour le moment.<br>
        <small>Les statistiques apparaîtront dès les premières saisies.</small></p>`;
      return;
    }

    const secteurMap = Object.fromEntries(secteurs.map(s => [s.id, s]));

    // ── Par secteur ──
    const parSecteur = {};
    for (const s of secteurs) {
      parSecteur[s.id] = {
        nom: s.nom, commune: s.commune,
        boites: nbFoyersSecteur(s),
        dons: 0, offerts: 0, refus: 0, absents: 0, montant: 0
      };
    }
    // Répartition horaire et par montant
    const parHeure = {};
    const parMontant = {};

    for (const p of passages) {
      const d = parSecteur[p.secteurId];
      if (d) {
        if (p.statut === "don")    { d.dons++;    d.montant += Number(p.montant || 0); }
        if (p.statut === "offert")   d.offerts++;
        if (p.statut === "refuse")   d.refus++;
        if (p.statut === "absent" || p.statut === "relance") d.absents++;
      }
      // Créneau horaire
      if (p.datePassage) {
        const h = new Date(p.datePassage).getHours();
        if (!parHeure[h]) parHeure[h] = { passages: 0, dons: 0, montant: 0 };
        parHeure[h].passages++;
        if (p.statut === "don") { parHeure[h].dons++; parHeure[h].montant += Number(p.montant || 0); }
      }
      // Montants les plus fréquents
      if (p.statut === "don" && p.montant > 0) {
        const m = Math.round(Number(p.montant));
        parMontant[m] = (parMontant[m] || 0) + 1;
      }
    }

    lignesSecteur = Object.values(parSecteur)
      .filter(d => d.dons + d.offerts + d.refus + d.absents > 0)
      .map(d => {
        const visites = d.dons + d.offerts + d.refus;
        const total = visites + d.absents;
        const calendriers = d.dons + d.offerts;
        return {
          ...d, visites, total, calendriers,
          tauxPlacement: d.boites > 0 ? (calendriers / d.boites) * 100 : null,
          tauxRefus: visites > 0 ? (d.refus / visites) * 100 : 0,
          tauxAbsence: total > 0 ? (d.absents / total) * 100 : 0,
          donMoyen: d.dons > 0 ? d.montant / d.dons : 0,
          avancement: d.boites > 0 ? (visites / d.boites) * 100 : null
        };
      })
      .sort((a, b) => b.montant - a.montant);

    // ── Chiffres globaux ──
    const gDons = lignesSecteur.reduce((s, d) => s + d.dons, 0);
    const gMontant = lignesSecteur.reduce((s, d) => s + d.montant, 0);
    const gVisites = lignesSecteur.reduce((s, d) => s + d.visites, 0);
    const gRefus = lignesSecteur.reduce((s, d) => s + d.refus, 0);
    const donMoyenGlobal = gDons > 0 ? gMontant / gDons : 0;
    const tauxRefusGlobal = gVisites > 0 ? (gRefus / gVisites) * 100 : 0;

    // ── Créneaux horaires ──
    const heures = Object.entries(parHeure)
      .map(([h, d]) => ({
        heure: Number(h), ...d,
        taux: d.passages > 0 ? (d.dons / d.passages) * 100 : 0,
        moyenne: d.dons > 0 ? d.montant / d.dons : 0
      }))
      .sort((a, b) => a.heure - b.heure);
    const maxPassages = Math.max(1, ...heures.map(h => h.passages));

    // ── Montants les plus donnés ──
    const montants = Object.entries(parMontant)
      .map(([m, n]) => ({ montant: Number(m), nb: n }))
      .sort((a, b) => b.nb - a.nb).slice(0, 8);
    const maxNb = Math.max(1, ...montants.map(m => m.nb));

    const coulTaux = (t) => t >= 45 ? "#16A34A" : t >= 30 ? "#EAB308" : t >= 20 ? "#F97316" : "#EF4444";

    el.innerHTML = `
      <div class="stats-grid" style="margin-bottom:20px;">
        <div class="stat-card stat-card--primary">
          <div class="stat-value">${formatMontant(donMoyenGlobal)}</div>
          <div class="stat-label">Don moyen</div>
        </div>
        <div class="stat-card">
          <div class="stat-value">${tauxRefusGlobal.toFixed(0)}%</div>
          <div class="stat-label">Taux de refus</div>
          <div class="stat-sub">${gRefus} refus sur ${gVisites} portes ouvertes</div>
        </div>
        <div class="stat-card">
          <div class="stat-value">${gDons}</div>
          <div class="stat-label">Dons enregistrés</div>
        </div>
      </div>

      <div class="section-block">
        <h2>Performance par secteur</h2>
        <div class="table-wrap">
          <table class="table">
            <thead><tr>
              <th>Secteur</th><th>Avancement</th><th>Taux de placement</th>
              <th>Don moyen</th><th>Refus</th><th>Absences</th><th>Collecté</th>
            </tr></thead>
            <tbody>
              ${lignesSecteur.map(d => `
                <tr>
                  <td><strong>${h(d.nom)}</strong>${d.commune !== d.nom ? `<br><small style="color:var(--ardoise-mid)">${h(d.commune)}</small>` : ''}</td>
                  <td>${d.avancement !== null ? `${d.avancement.toFixed(0)}%<br><small style="color:var(--ardoise-mid)">${d.visites}/${d.boites}</small>` : '—'}</td>
                  <td>${d.tauxPlacement !== null
                        ? `<strong style="color:${coulTaux(d.tauxPlacement)}">${d.tauxPlacement.toFixed(0)}%</strong><br><small style="color:var(--ardoise-mid)">${d.calendriers} cal.</small>`
                        : `${d.calendriers} cal.`}</td>
                  <td>${d.dons > 0 ? formatMontant(d.donMoyen) : '—'}</td>
                  <td>${d.tauxRefus.toFixed(0)}%<br><small style="color:var(--ardoise-mid)">${d.refus}</small></td>
                  <td>${d.tauxAbsence.toFixed(0)}%<br><small style="color:var(--ardoise-mid)">${d.absents}</small></td>
                  <td><strong>${formatMontant(d.montant)}</strong></td>
                </tr>`).join('')}
            </tbody>
          </table>
        </div>
        <p style="font-size:.76rem;color:var(--ardoise-mid);margin-top:8px;">
          Le <strong>taux de placement</strong> rapporte les calendriers distribués au nombre total de boîtes du secteur.
          C'est l'indicateur à utiliser pour fixer les objectifs de l'an prochain.
        </p>
      </div>

      ${heures.length > 0 ? `
      <div class="section-block">
        <h2>Créneaux horaires</h2>
        <div class="st-heures">
          ${heures.map(h => `
            <div class="st-heure">
              <div class="st-h-barre-zone">
                <div class="st-h-taux">${h.taux.toFixed(0)}%</div>
                <div class="st-h-barre" style="height:${Math.round((h.passages/maxPassages)*100)}%;background:${coulTaux(h.taux)}"></div>
              </div>
              <div class="st-h-label">${h.heure}h</div>
              <div class="st-h-nb">${h.passages}</div>
            </div>`).join('')}
        </div>
        <p style="font-size:.76rem;color:var(--ardoise-mid);margin-top:8px;">
          Hauteur = nombre de passages · Couleur et pourcentage = part de dons obtenus.
          Les créneaux verts sont les plus productifs.
        </p>
      </div>` : ''}

      ${montants.length > 0 ? `
      <div class="section-block">
        <h2>Montants les plus donnés</h2>
        <div class="st-montants">
          ${montants.map(m => `
            <div class="st-montant">
              <div class="st-m-val">${m.montant} €</div>
              <div class="st-m-barre-zone">
                <div class="st-m-barre" style="width:${Math.round((m.nb/maxNb)*100)}%"></div>
              </div>
              <div class="st-m-nb">${m.nb}×</div>
            </div>`).join('')}
        </div>
      </div>` : ''}
    `;

    document.getElementById("btn-export-stats")?.addEventListener("click", () => {
      let csv = "Secteur;Commune;Boîtes;Visitées;Avancement (%);Calendriers;Taux placement (%);Dons;Don moyen (€);Refus;Taux refus (%);Absents;Taux absence (%);Collecté (€)\n";
      for (const d of lignesSecteur) {
        csv += [d.nom, d.commune, d.boites, d.visites].map(celluleCSV).join(';') + ';' 
             + `"${d.avancement !== null ? d.avancement.toFixed(1) : ''}";"${d.calendriers}";`
             + `"${d.tauxPlacement !== null ? d.tauxPlacement.toFixed(1) : ''}";"${d.dons}";`
             + `"${d.donMoyen.toFixed(2)}";"${d.refus}";"${d.tauxRefus.toFixed(1)}";`
             + `"${d.absents}";"${d.tauxAbsence.toFixed(1)}";"${d.montant.toFixed(2)}"\n`;
      }
      csv += "\n\nCRÉNEAUX HORAIRES\nHeure;Passages;Dons;Taux de dons (%);Don moyen (€)\n";
      for (const h of heures) {
        csv += `"${h.heure}h";"${h.passages}";"${h.dons}";"${h.taux.toFixed(1)}";"${h.moyenne.toFixed(2)}"\n`;
      }
      telechargerCSV(csv, `statistiques-${dateLocaleISO()}.csv`);
      toast("Statistiques exportées", "success");
    });

  } catch(e) {
    document.getElementById("stats-content").innerHTML =
      `<p class="empty-state">Erreur : ${h(e.message)}</p>`;
  }
}

