async function renderJournal() {
  if (APP.role !== "admin") { naviguer("#login"); return; }
  stopUnsubs();

  document.getElementById("main").innerHTML = layoutAdmin("#journal", `
    <div class="page-header">
      <h1>📜 Journal des modifications</h1>
      <button id="btn-export-journal" class="btn btn--ghost">⬇️ Exporter</button>
    </div>
    <p style="font-size:.85rem;color:var(--ardoise-mid);margin-bottom:16px;line-height:1.5;">
      Trace des corrections et suppressions de passages. Utile en cas d'écart constaté au moment des comptes.
    </p>
    <div class="filter-bar">
      <input id="jr-recherche" class="input input--sm" placeholder="🔍 Filtrer par personne, adresse…" style="max-width:300px;">
      <select id="jr-type" class="input input--sm" style="max-width:200px;">
        <option value="">Toutes les actions</option>
        <option value="modification">Corrections</option>
        <option value="suppression">Suppressions</option>
      </select>
    </div>
    <div id="journal-content"><div class="loader">Chargement…</div></div>
  `);
  bindLogout();

  let entrees = [];

  function afficher() {
    const q = (document.getElementById("jr-recherche")?.value || "").toLowerCase().trim();
    const type = document.getElementById("jr-type")?.value || "";
    const filtrees = entrees.filter(e => {
      if (type && e.action !== type) return false;
      if (!q) return true;
      return [e.parQui, e.equipeNom, e.avant, e.apres, e.contexte]
        .filter(Boolean).join(" ").toLowerCase().includes(q);
    });

    const el = document.getElementById("journal-content");
    if (!el) return;

    if (entrees.length === 0) {
      el.innerHTML = `<p class="empty-state">Aucune modification enregistrée.<br>
        <small>Les corrections et suppressions apparaîtront ici.</small></p>`;
      return;
    }

    const ecart = ecartCumule(filtrees);
    const nbSupp = filtrees.filter(e => e.action === "suppression").length;
    const nbMod  = filtrees.filter(e => e.action === "modification").length;

    el.innerHTML = `
      <div class="stats-grid" style="margin-bottom:16px;">
        <div class="stat-card"><div class="stat-value">${nbMod}</div><div class="stat-label">Correction${nbMod>1?'s':''}</div></div>
        <div class="stat-card"><div class="stat-value">${nbSupp}</div><div class="stat-label">Suppression${nbSupp>1?'s':''}</div></div>
        <div class="stat-card ${Math.abs(ecart) > 0.009 ? 'stat-card--alerte' : ''}">
          <div class="stat-value" style="color:${ecart < -0.009 ? 'var(--rouge)' : ecart > 0.009 ? 'var(--vert)' : 'var(--ardoise)'}">
            ${ecart >= 0 ? '+' : ''}${formatMontant(ecart)}
          </div>
          <div class="stat-label">Écart cumulé</div>
          <div class="stat-sub">effet des corrections sur les montants</div>
        </div>
      </div>

      <div class="table-wrap">
        <table class="table">
          <thead><tr><th>Quand</th><th>Qui</th><th>Action</th><th>Avant</th><th>Après</th><th>Écart</th></tr></thead>
          <tbody>
            ${filtrees.map(e => {
              const d = e.date ? new Date(e.date) : null;
              const ec = (e.montantApres || 0) - (e.montantAvant || 0);
              return `<tr class="${e.action === 'suppression' ? 'jr-supp' : ''}">
                <td style="white-space:nowrap">
                  ${d ? d.toLocaleDateString('fr-FR',{day:'2-digit',month:'short'}) : '—'}
                  <br><small style="color:var(--ardoise-mid)">${d ? d.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}) : ''}</small>
                </td>
                <td>${h(e.parQui || '—')}${e.equipeNom ? `<br><small style="color:var(--ardoise-mid)">${h(e.equipeNom)}</small>` : ''}</td>
                <td><span class="jr-badge jr-badge--${e.action}">${ACTION_LABEL[e.action] || e.action}</span>
                    ${e.contexte ? `<br><small style="color:var(--ardoise-mid)">${e.contexte}</small>` : ''}</td>
                <td style="font-size:.82rem">${e.avant || '—'}</td>
                <td style="font-size:.82rem">${e.apres || '<em style="color:var(--rouge)">supprimé</em>'}</td>
                <td style="font-weight:700;color:${ec < -0.009 ? 'var(--rouge)' : ec > 0.009 ? 'var(--vert)' : 'var(--ardoise-mid)'}">
                  ${Math.abs(ec) > 0.009 ? (ec > 0 ? '+' : '') + formatMontant(ec) : '—'}
                </td>
              </tr>`;
            }).join('')}
          </tbody>
        </table>
      </div>
      ${filtrees.length === 0 ? '<p class="empty-state">Aucun résultat pour ce filtre.</p>' : ''}
    `;
  }

  try {
    entrees = await lireJournal({ limite: 400 });
    afficher();
  } catch(e) {
    document.getElementById("journal-content").innerHTML =
      `<p class="empty-state">Erreur de chargement : ${h(e.message)}</p>`;
  }

  document.getElementById("jr-recherche")?.addEventListener("input", afficher);
  document.getElementById("jr-type")?.addEventListener("change", afficher);

  document.getElementById("btn-export-journal")?.addEventListener("click", () => {
    let csv = "Date;Heure;Qui;Équipe;Action;Contexte;Avant;Après;Écart (€)\n";
    for (const e of entrees) {
      const d = e.date ? new Date(e.date) : null;
      const ec = (e.montantApres || 0) - (e.montantAvant || 0);
      csv += `"${d ? d.toLocaleDateString('fr-FR') : ''}";"${d ? d.toLocaleTimeString('fr-FR') : ''}";`
            + [e.parQui || '', e.equipeNom || '', ACTION_LABEL[e.action] || e.action].map(celluleCSV).join(';') + ';' 
           + `"${e.contexte || ''}";"${e.avant || ''}";"${e.apres || ''}";"${ec.toFixed(2)}"\n`;
    }
    telechargerCSV(csv, `journal-modifications-${dateLocaleISO()}.csv`);
    toast("Journal exporté", "success");
  });
}

