async function renderConfig() {
  if (APP.role !== "admin") { naviguer("#login"); return; }
  stopUnsubs();

  const config = await lireConfig() || {};
  document.getElementById("main").innerHTML = layoutAdmin("#config", `
    <div class="page-header"><h1>Configuration de la tournée</h1></div>
    <div class="form-card">
      <label class="label">Année</label>
      <input id="cfg-annee" class="input" value="${config.annee || new Date().getFullYear()}" type="number">
      <label class="label">Date de début</label>
      <input id="cfg-debut" class="input" type="date" value="${config.dateDebut || ''}">
      <label class="label">Date de fin</label>
      <input id="cfg-fin" class="input" type="date" value="${config.dateFin || ''}">
      <label class="label">Objectif de collecte (€)</label>
      <input id="cfg-objectif" class="input" type="number" value="${config.objectif || ''}">
      <label class="label">Message affiché aux Amicalistes</label>
      <textarea id="cfg-message" class="input textarea" rows="3">${h(config.messageEquipiers || '')}</textarea>
      <label class="label">Admins autorisés (emails, un par ligne)</label>
      <textarea id="cfg-admins" class="input textarea" rows="5">${(config.admins || []).join('\n')}</textarea>
      <button id="btn-save-config" class="btn btn--primary">💾 Enregistrer</button>
    </div>

    <div class="form-card" style="margin-top:24px;">
      <h2 style="font-size:1.05rem;font-weight:700;margin-bottom:8px;">🔐 Sécurité des codes PIN</h2>
      <p style="font-size:.85rem;color:var(--ardoise-mid);margin-bottom:16px;line-height:1.5;">
        Déplace les codes PIN vers un stockage où il faut connaître un code pour le lire.
        À lancer une seule fois. Les codes restent identiques, rien ne change pour les équipiers.
      </p>
      <div id="migration-etat" class="notif-etat"></div>
      <button id="btn-migrer-pins" class="btn btn--primary">🔐 Sécuriser les codes PIN</button>
    </div>

    <div class="form-card form-card--danger" style="margin-top:24px;">
      <h2 style="font-size:1.05rem;font-weight:700;margin-bottom:8px;">🧹 Effacer les saisies</h2>
      <p style="font-size:.85rem;color:var(--ardoise-mid);margin-bottom:16px;line-height:1.5;">
        Supprime <strong>tous les passages</strong> et remet les compteurs des secteurs à zéro.
        Les secteurs, les équipes et leurs affectations sont conservés.
        Pratique pour repartir propre après une phase de test.
      </p>
      <div id="effacer-etat" class="notif-etat"></div>
      <label class="checkbox-label" style="margin-bottom:14px;">
        <input type="checkbox" id="eff-journal">
        Effacer aussi le journal des modifications
      </label>
      <button id="btn-effacer-passages" class="btn btn--danger">🧹 Effacer tous les passages</button>
    </div>

    <div class="form-card" style="margin-top:24px;">
      <h2 style="font-size:1.05rem;font-weight:700;margin-bottom:8px;">🛟 Sauvegarde</h2>
      <p style="font-size:.85rem;color:var(--ardoise-mid);margin-bottom:16px;line-height:1.5;">
        Télécharge l'intégralité des données (secteurs, équipes, passages, historique)
        dans un fichier JSON. À conserver hors de l'application, par précaution.
      </p>
      <button id="btn-sauvegarde" class="btn btn--primary">⬇️ Télécharger la sauvegarde</button>
    </div>

    ${FEATURE_NOTIFS_RESUME ? `
    <div class="form-card" style="margin-top:24px;">
      <h2 style="font-size:1.05rem;font-weight:700;margin-bottom:8px;">🔔 Résumé quotidien</h2>
      <p style="font-size:.85rem;color:var(--ardoise-mid);margin-bottom:16px;line-height:1.5;">
        Reçois une notification avec le bilan du jour (collecte, avancement, top équipes).
        La notification apparaît si l'application est ouverte, même en arrière-plan.
        Ce réglage est propre à cet appareil.
      </p>

      <div id="notif-etat" class="notif-etat"></div>

      <label class="label">Heure d'envoi</label>
      <input id="cfg-heure-resume" class="input" type="number" min="0" max="23" style="max-width:120px;">

      <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:16px;">
        <button id="btn-activer-notifs" class="btn btn--primary">🔔 Activer les notifications</button>
        <button id="btn-tester-notif" class="btn btn--ghost">📤 Tester maintenant</button>
      </div>
    </div>` : ''}
  `);
  bindLogout();

  // ── Réglages notifications (en attente de validation du bureau) ──
  if (FEATURE_NOTIFS_RESUME) {
  const inputHeure = document.getElementById("cfg-heure-resume");
  if (inputHeure) inputHeure.value = getHeureResume();

  function majEtatNotifs() {
    const el = document.getElementById("notif-etat");
    const btnActiver = document.getElementById("btn-activer-notifs");
    if (!el) return;
    const perm = notifsPermission();
    if (perm === "unsupported") {
      el.className = "notif-etat notif-etat--off";
      el.textContent = "⚠️ Ce navigateur ne supporte pas les notifications.";
      btnActiver && (btnActiver.style.display = "none");
    } else if (perm === "granted") {
      el.className = "notif-etat notif-etat--on";
      el.textContent = `✅ Notifications activées — résumé prévu à ${getHeureResume()}h` +
        (resumeDejaEnvoyeAujourdhui() ? " (déjà envoyé aujourd'hui)" : "");
      btnActiver && (btnActiver.style.display = "none");
    } else if (perm === "denied") {
      el.className = "notif-etat notif-etat--off";
      el.textContent = "🚫 Notifications bloquées. Autorise-les dans les réglages du navigateur pour ce site.";
      btnActiver && (btnActiver.style.display = "none");
    } else {
      el.className = "notif-etat notif-etat--pending";
      el.textContent = "Notifications pas encore activées sur cet appareil.";
      btnActiver && (btnActiver.style.display = "");
    }
  }
  majEtatNotifs();

  inputHeure?.addEventListener("change", () => {
    const h = setHeureResume(inputHeure.value);
    inputHeure.value = h;
    toast(`Résumé quotidien réglé à ${h}h`, "success");
    majEtatNotifs();
  });

  document.getElementById("btn-activer-notifs")?.addEventListener("click", async () => {
    try {
      const perm = await demanderPermissionNotifs();
      if (perm === "granted") {
        toast("Notifications activées ✅", "success");
        demarrerPlanificateurResume();
      } else {
        toast("Permission refusée", "error");
      }
      majEtatNotifs();
    } catch(e) { toast(e.message, "error"); }
  });

  document.getElementById("btn-tester-notif")?.addEventListener("click", async () => {
    const btn = document.getElementById("btn-tester-notif");
    setLoading(btn, true);
    try {
      const resume = await envoyerResumeMaintenant(chargerDonneesResume, APP.organisationLogo);
      toast("Notification envoyée : " + resume.titre, "success");
      majEtatNotifs();
    } catch(e) { toast("Erreur : " + e.message, "error"); }
    setLoading(btn, false);
  });
  } // fin FEATURE_NOTIFS_RESUME

  // État de la migration des PIN
  (async () => {
    const el = document.getElementById("migration-etat");
    if (!el) return;
    try {
      const [equipes, pins] = await Promise.all([lireEquipes(), lirePins()]);
      const restants = equipes.filter(e => e.pin).length;
      const migres = Object.keys(pins).length;
      if (restants === 0 && migres > 0) {
        el.className = "notif-etat notif-etat--on";
        el.textContent = `✅ ${migres} code(s) déjà sécurisé(s).`;
        const b = document.getElementById("btn-migrer-pins");
        if (b) b.style.display = "none";
      } else {
        el.className = "notif-etat notif-etat--pending";
        el.textContent = `${restants} code(s) encore stocké(s) en clair dans les équipes.`;
      }
    } catch(e) {
      el.className = "notif-etat notif-etat--off";
      el.textContent = "Impossible de vérifier l'état : " + e.message;
    }
  })();

  document.getElementById("btn-migrer-pins")?.addEventListener("click", async () => {
    if (!confirm("Déplacer les codes PIN vers le stockage sécurisé ?\n\n" +
                 "Les codes restent les mêmes, les équipiers ne verront aucun changement.\n" +
                 "Pense à avoir téléchargé une sauvegarde avant.")) return;
    const btn = document.getElementById("btn-migrer-pins");
    setLoading(btn, true);
    try {
      const r = await migrerPins();
      toast(`${r.deplaces} code(s) sécurisé(s)${r.conflits ? ` · ${r.conflits} conflit(s)` : ''}`,
            r.conflits ? "error" : "success");
      naviguer("#config");
    } catch(e) {
      toast("Erreur : " + e.message, "error");
      setLoading(btn, false);
    }
  });

  // Nombre de passages actuellement enregistrés
  (async () => {
    const el = document.getElementById("effacer-etat");
    if (!el) return;
    try {
      const p = await fsGetAllOrg(COLLECTIONS.PASSAGES);
      if (p.length === 0) {
        el.className = "notif-etat notif-etat--on";
        el.textContent = "Aucun passage enregistré, rien à effacer.";
        const b = document.getElementById("btn-effacer-passages");
        if (b) b.disabled = true;
      } else {
        const montant = p.filter(x => x.statut === "don")
                         .reduce((s, x) => s + Number(x.montant || 0), 0);
        el.className = "notif-etat notif-etat--pending";
        let nj = 0;
        try { nj = (await lireJournal({ limite: 9999 })).length; } catch(e) {}
        el.textContent = `${p.length} passage(s) enregistré(s), pour ${formatMontant(montant)} collecté(s).`
                       + (nj ? ` Journal : ${nj} trace(s).` : '');
      }
    } catch(e) {
      el.className = "notif-etat notif-etat--off";
      el.textContent = "Impossible de compter les passages : " + e.message;
    }
  })();

  document.getElementById("btn-effacer-passages")?.addEventListener("click", async () => {
    const passages = await fsGetAllOrg(COLLECTIONS.PASSAGES);
    if (passages.length === 0) { toast("Aucun passage à effacer", "info"); return; }

    const montant = passages.filter(x => x.statut === "don")
                            .reduce((s, x) => s + Number(x.montant || 0), 0);

    const avecJournal = document.getElementById("eff-journal")?.checked || false;

    if (!confirm(
      `⚠️ EFFACER TOUS LES PASSAGES ?\n\n` +
      `${passages.length} passage(s) et ${formatMontant(montant)} de collecte vont être définitivement supprimés.\n` +
      (avecJournal ? `Le journal des modifications sera également vidé.\n` : '') +
      `Les secteurs et les équipes seront conservés.\n\n` +
      `Pense à avoir téléchargé une sauvegarde.`
    )) return;

    const saisie = prompt(
      `Dernière confirmation.\n\nTape EFFACER (en majuscules) pour supprimer les ${passages.length} passages :`
    );
    if (saisie !== "EFFACER") { toast("Effacement annulé", "info"); return; }

    const btn = document.getElementById("btn-effacer-passages");
    setLoading(btn, true);
    try {
      const r = await effacerTousLesPassages();
      let msgJournal = '';
      if (avecJournal) {
        try {
          const nj = await viderJournal();
          msgJournal = ` · ${nj} trace(s) de journal effacée(s)`;
        } catch(e) { msgJournal = ' · journal non vidé'; }
      }
      toast(`${r.supprimes} passage(s) effacé(s)${r.erreurs ? ` · ${r.erreurs} erreur(s)` : ''} · ${r.secteurs} secteur(s) remis à zéro${msgJournal}`,
            r.erreurs ? "error" : "success");
      naviguer("#config");
    } catch(e) {
      toast("Erreur : " + e.message, "error");
      setLoading(btn, false);
    }
  });

  document.getElementById("btn-sauvegarde")?.addEventListener("click", async () => {
    const btn = document.getElementById("btn-sauvegarde");
    setLoading(btn, true);
    try {
      const [secteurs, equipes, passages, saisons, cfg] = await Promise.all([
        fsGetAllOrg(COLLECTIONS.SECTEURS),
        fsGetAllOrg(COLLECTIONS.EQUIPES),
        fsGetAllOrg(COLLECTIONS.PASSAGES),
        exporterHistoriqueComplet(),
        lireConfig()
      ]);
      let pins = {};
      try { pins = await lirePins(); } catch(e) {}
      const dump = {
        genere: new Date().toISOString(),
        version: 1,
        parQui: APP.user?.email || '',
        config: cfg || {},
        secteurs,
        equipes: equipes.map(e => ({ ...e, pin: pins[e.id] || e.pin || null })),
        passages,
        historique_saisons: saisons
      };
      const blob = new Blob([JSON.stringify(dump, null, 1)], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `sauvegarde-calendriers-${dateLocaleISO()}.json`;
      document.body.appendChild(a); a.click(); document.body.removeChild(a);
      URL.revokeObjectURL(url);
      toast(`Sauvegarde : ${secteurs.length} secteurs · ${equipes.length} équipes · ${passages.length} passages`, "success");
    } catch(e) {
      toast("Erreur : " + e.message, "error");
    }
    setLoading(btn, false);
  });

  document.getElementById("btn-save-config")?.addEventListener("click", async () => {
    const admins = [...new Set(document.getElementById("cfg-admins").value
      .split('\n').map(e => e.trim().toLowerCase()).filter(Boolean))];
    try {
      await sauvegarderConfig({
        annee:           Number(document.getElementById("cfg-annee").value),
        dateDebut:       document.getElementById("cfg-debut").value,
        dateFin:         document.getElementById("cfg-fin").value,
        objectif:        Number(document.getElementById("cfg-objectif").value),
        messageEquipiers: document.getElementById("cfg-message").value.trim(),
        admins
      });
      // Synchronisation réelle de /admins : ajout ET révocation des anciens comptes.
      const existants = await fsGetAll(COLLECTIONS.ADMINS);
      const autorises = new Set(admins);
      for (const ancien of existants) {
        if (!autorises.has(String(ancien.id).toLowerCase())) await fsDelete(COLLECTIONS.ADMINS, ancien.id);
      }
      for (const email of admins) {
        await fsSet(COLLECTIONS.ADMINS, email, { email, grantedAt: new Date().toISOString() });
      }
      toast("Configuration sauvegardée ✅", "success");
    } catch(e) { toast(e.message, "error"); }
  });
}

